export class Vector {
  constructor() { this.x = 0; }
  set(x) { this.x = x; return this; }
}

export class Select {
  /** @param {boolean} flag @param {Vector} target */
  static choose(flag, target) {
    if (flag) return null;
    return target.set(5);
  }
}

export function choose(flag, target) {
  if (flag) return null;
  return target;
}
